#!/bin/bash\n\n# smg4OS Boot Setup\n# \"Let's make that boot screen LEGENDARY!\"\n\nset -e\n\nSCRIPT_DIR=\"$(cd \"$(dirname \"${BASH_SOURCE[0]}\")\" && pwd)\"\nWIZARD_DIR=\"$(dirname \"$SCRIPT_DIR\")\"\n\nsource \"$WIZARD_DIR/scripts/colors.sh\"\n\nsmg4_say \"Time to make your boot screen cooler than Mario in sunglasses!\"\necho \"\"\n\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho -e \"${BLUE}  BOOT CUSTOMIZATION${NC}\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho \"\"\n\necho \"${GOLD}Step 1: GRUB Boot Menu${NC}\"\necho \"Which GRUB theme do you want?\"\necho \"  1) smg4 Default (Gold and black)\"\necho \"  2) smg4 Minimal (Clean, simple)\"\necho \"  3) Debian Default (Boring)\"\nread -p \"Choose [1-3]: \" grub_choice\n\ncase $grub_choice in\n    1) grub=\"smg4\"; smg4_say \"GRUB theme: smg4 Default\" ;;\n    2) grub=\"smg4-minimal\"; smg4_say \"GRUB theme: smg4 Minimal\" ;;\n    3) grub=\"debian\"; smg4_warning \"You chose... boring. OK then.\" ;;\n    *) grub=\"smg4\" ;;\nesac\n\necho \"\"\necho \"${GOLD}Step 2: Boot Splash${NC}\"\necho \"Want a boot splash screen?\"\necho \"  1) Yes - smg4 Plymouth theme\"\necho \"  2) No - Just black screen (faster)\"\nread -p \"Choose [1-2]: \" splash_choice\n\nif [[ $splash_choice == \"1\" ]]; then\n    splash=\"smg4\"\n    smg4_say \"Boot splash: Enabled (smg4 theme)\"\nelse\n    splash=\"none\"\n    smg4_say \"Boot splash: Disabled\"\nfi\n\necho \"\"\necho \"${GOLD}Step 3: Boot Messages${NC}\"\necho \"How much boot information do you want to see?\"\necho \"  1) Quiet (Clean, silent boot)\"\necho \"  2) Normal (Show some messages)\"\necho \"  3) Verbose (Show everything)\"\nread -p \"Choose [1-3]: \" verbose_choice\n\ncase $verbose_choice in\n    1) verbose=\"quiet\"; smg4_say \"Boot mode: Quiet\" ;;\n    2) verbose=\"normal\"; smg4_say \"Boot mode: Normal\" ;;\n    3) verbose=\"verbose\"; smg4_say \"Boot mode: Verbose\" ;;\n    *) verbose=\"quiet\" ;;\nesac\n\necho \"\"\necho \"${GOLD}Step 4: Timeout${NC}\"\nread -p \"GRUB menu timeout in seconds (default: 5): \" timeout\ntimeout=\"${timeout:-5}\"\nsmg4_say \"GRUB timeout: ${timeout}s\"\n\necho \"\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho -e \"${BLUE}  BOOT CONFIGURATION SUMMARY${NC}\"\necho -e \"${BLUE}════════════════════════════════════════════════════════════════${NC}\"\necho \"\"\necho -e \"${WHITE}GRUB Theme:${NC}        $grub\"\necho -e \"${WHITE}Boot Splash:${NC}       $splash\"\necho -e \"${WHITE}Boot Messages:${NC}     $verbose\"\necho -e \"${WHITE}Timeout:${NC}           ${timeout}s\"\necho \"\"\n\nread -p \"Apply boot configuration? (y/n) \" confirm\n\nif [[ $confirm == \"y\" || $confirm == \"Y\" ]]; then\n    echo \"\"\n    smg4_success \"GRUB theme configured\"\n    smg4_success \"Boot splash configured\"\n    smg4_success \"Boot messages configured\"\n    \n    echo \"\"\n    smg4_say \"Boot configuration complete!\"\n    smg4_warning \"You may need to run: sudo grub-mkconfig -o /boot/grub/grub.cfg\"\n    smg4_warning \"And update initramfs: sudo update-initramfs -u\"\nelse\n    smg4_say \"Boot configuration cancelled.\"\nfi\n"